<script setup lang="ts">
import { computed } from 'vue'
import {emptyValue,type EditorSpec} from './api/beta1-owner.ts'
const props=defineProps<{spec:EditorSpec;modelValue:unknown;path:string;disabled?:boolean;scope?:string}>()
const emit=defineEmits<{ 'update:modelValue':[value:unknown] }>()
const record=computed(()=>(props.modelValue??{}) as Record<string,unknown>)
const entries=computed(()=>Object.entries(props.spec.fields??{}))
const values=computed(()=>Array.isArray(props.modelValue)?props.modelValue:[])
const names:Record<string,string>={namespace:'当前角色范围',bot_id:'AstrBot 身份',persona_id:'角色身份',runtime_identity:'实际安装身份',authority_id:'Authority 身份',installation_id:'安装身份',schema:'协议版本',plan_id:'计划标识',policy_id:'政策标识',revision:'版本',version:'版本',expected_revision:'预期当前版本',expected_policy_revision:'预期政策版本',plan_ref:'计划引用',policy_ref:'政策引用',window_ref:'窗口引用',candidate_ref:'候选引用',source_refs:'来源引用',audience:'授权受众',purpose:'授权用途',state:'状态',blocks:'人格块',values:'价值规则',claim:'身份或行为立场',block_id:'人格块标识',kind:'类型',plasticity:'可塑性',label:'说明',roles:'场景角色',norms:'场景规范',required_checks:'必需检查',valid_from:'起始时间（UTC 秒）',valid_until:'有效期限（UTC 秒）',parent_root_grant_ref:'原 Root 授权引用',parent_root_grant_id:'原 Root 授权标识',parent_root_grant_version:'原 Root 授权版本',parent_root_grant_digest:'原 Root 授权摘要',target_ref:'真实目标引用',project_ref:'项目引用',recipe_ref:'活动方案引用',recipe_revision:'活动方案版本',goal_ref:'目标引用',definition:'政策定义',plan:'长期计划',window:'当前协作窗口',value:'实际登记内容',conditions:'条件与布尔期望',scope_refs:'适用范围',exclusions:'排除条件',milestones:'里程碑',node_drafts:'窗口节点',success_predicate:'成功条件',cue_predicate:'触发条件',stop_predicate:'停止条件',source_note_input:'已固定的来源笔记输入',window_anchor_utc:'窗口锚点（UTC 秒）',window_seconds:'窗口长度（秒）',execution_seconds:'单次执行期限（秒）',minimum_interval_seconds:'最小间隔（秒）',maximum_occurrences_per_window:'每窗口最多次数',original_valid_until_utc:'原授权期限（UTC 秒）',miss_policy:'错过策略',executor_kind:'执行类型',cancellation_generation:'取消代次',general_request:'已有成长采用原件',expected_persona_head:'预期人格 Head',rejected_strategy_ref:'被回退策略',occurrence_ref:'本次习惯引用',reason_ref:'错过原因原件',event_time_as_of:'事件时间截面（UTC 秒）',knowledge_as_of:'知识序列截面',coverage_bound:'单页上限',cursor:'下一页游标',perspective_version:'视角版本',view_version:'已有世界视图版本',communication_grant_version:'已有沟通许可版本',scene_ref:'场景引用',conversation_epoch:'会话代次'}
function label(key:string){return names[key]??key.replaceAll('_',' ')}
function setField(key:string,value:unknown){emit('update:modelValue',{...record.value,[key]:value})}
function setItem(index:number,value:unknown){const next=[...values.value];next[index]=value;emit('update:modelValue',next)}
function add(){emit('update:modelValue',[...values.value,emptyValue(props.spec.item!,props.scope)])}
function remove(index:number){emit('update:modelValue',values.value.filter((_,i)=>i!==index))}
function enable(event:Event){emit('update:modelValue',(event.target as HTMLInputElement).checked?emptyValue({...props.spec,nullable:false},props.scope):null)}
function number(event:Event){const input=(event.target as HTMLInputElement).value;emit('update:modelValue',input===''?null:Number(input))}
</script>
<template>
 <div class="structured-field">
  <label v-if="spec.nullable" class="structured-optional"><input type="checkbox" :checked="modelValue!==null" :disabled="disabled" @change="enable">提供此可选值（未勾选为明确空值）</label>
  <template v-if="!spec.nullable||modelValue!==null">
   <dl v-if="spec.kind==='object'" class="structured-object"><div v-for="[key,field] in entries" :key="key"><dt><label :for="path+'-'+key">{{label(key)}} <small>{{key}}</small></label></dt><dd><StructuredFields :spec="field" :model-value="record[key]" :path="path+'-'+key" :scope="scope" :disabled="disabled||['bot_id','persona_id'].includes(key)" @update:model-value="setField(key,$event)"/></dd></div></dl>
   <div v-else-if="spec.kind==='array'||spec.kind==='tuple'" class="structured-list"><p v-if="!values.length">尚无条目。</p><div v-for="(value,index) in values" :key="index" class="structured-item"><span class="structured-index">{{index+1}}</span><StructuredFields :spec="spec.kind==='array'?spec.item!:spec.items![index]" :model-value="value" :path="path+'-'+index" :scope="scope" :disabled="disabled" @update:model-value="setItem(index,$event)"/><button v-if="spec.kind==='array'" type="button" :disabled="disabled" @click="remove(index)">移除</button></div><button v-if="spec.kind==='array'" type="button" :disabled="disabled" @click="add">增加条目</button></div>
   <input v-else-if="spec.constant!==undefined" :id="path" :value="spec.constant" readonly aria-label="协议常量">
   <select v-else-if="spec.choices" :id="path" :value="modelValue" :disabled="disabled" @change="emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option value="">请选择实际选项</option><option v-for="item in spec.choices" :key="item" :value="item">{{item}}</option></select>
   <label v-else-if="spec.kind==='boolean'" class="structured-boolean"><input :id="path" type="checkbox" :checked="modelValue===true" :disabled="disabled" @change="emit('update:modelValue',($event.target as HTMLInputElement).checked)">{{modelValue===true?'是':'否'}}</label>
   <input v-else-if="spec.kind==='integer'||spec.kind==='number'" :id="path" type="number" :step="spec.kind==='integer'?1:'any'" :value="typeof modelValue==='number'?modelValue:''" :disabled="disabled" @input="number">
   <textarea v-else :id="path" :value="typeof modelValue==='string'?modelValue:''" :disabled="disabled" rows="2" autocomplete="off" spellcheck="false" @input="emit('update:modelValue',($event.target as HTMLTextAreaElement).value)"></textarea>
  </template>
 </div>
</template>
<style scoped>
.structured-field{min-width:0}.structured-object{margin:0}.structured-object>div{padding:10px 0;border-bottom:1px solid var(--line)}.structured-object dt{font-size:12px;margin-bottom:6px}.structured-object dt small{font-size:10px;color:var(--muted);margin-left:8px}.structured-object dd{margin:0;padding-left:12px;border-left:1px solid var(--line)}.structured-field :is(input:not([type=checkbox]),select,textarea){box-sizing:border-box;width:100%;min-height:44px;font:inherit;line-height:1.6;color:var(--ink);background:var(--surface);padding:9px;border:1px solid var(--line);border-radius:3px}.structured-field textarea{resize:vertical}.structured-field input[readonly]{color:var(--muted)}.structured-field :is(button,input,select,textarea):focus-visible{outline:2px solid var(--focus);outline-offset:3px}.structured-field button{font:inherit;min-height:40px;padding:7px 12px;border:1px solid var(--line);border-radius:3px;background:var(--button);color:var(--ink);cursor:pointer}.structured-field :disabled{color:var(--disabled-ink);cursor:default}.structured-list{padding:8px 0}.structured-list>p{font-size:12px;color:var(--muted)}.structured-item{display:grid;grid-template-columns:20px minmax(0,1fr) auto;gap:8px;align-items:start;margin-bottom:10px}.structured-index{font-size:11px;color:var(--muted);padding-top:10px}.structured-optional,.structured-boolean{display:flex;gap:8px;align-items:center;min-height:40px;font-size:12px}.structured-optional{color:var(--muted)}@media(max-width:600px){.structured-item{grid-template-columns:18px minmax(0,1fr)}.structured-item>button{grid-column:2;justify-self:start}.structured-object dd{padding-left:8px}}
</style>
